280	    @Override
281	    @Transactional(readOnly = true)
282	    public boolean isTelephoneInUse(String telephone) throws DataAccessException {
283	        String normalized = ownerMapper.normalizeTelephone(telephone);
284	        if (normalized == null) {
285	            return false;
286	        }
287	        return ownerRepository.findAll().stream()
288	            .map(existing -> ownerMapper.normalizeTelephone(existing.getTelephone()))
289	            .anyMatch(normalized::equals);
290	    }
291	
292	    @Override
293	    @Transactional(readOnly = true)
294	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
295	        String normalizedLastName = normalizeForComparison(lastName);
296	        String normalizedAddress = normalizeForComparison(address);
297	        if (normalizedLastName == null || normalizedAddress == null) {
298	            return false;
299	        }
300	        return ownerRepository.findAll().stream()
301	            .anyMatch(existing -> inHousehold(existing, normalizedLastName, normalizedAddress));
302	    }
303	
304	    /**
305	     * Canonicalize a free-text value for equality comparison: trim, collapse every run of
306	     * whitespace to a single space and lower-case the result, so values that differ only in
307	     * letter case or incidental whitespace are treated as equal. Shared by the household
308	     * (last name / address) and per-city matching rules.
309	     */
310	    private String normalizeForComparison(String value) {
311	        if (value == null) {
312	            return null;
313	        }
314	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
315	    }
316	
317	    /**
318	     * Single definition of household membership: an owner belongs to the household identified by
319	     * the given already-normalized last name and address when its own normalized last name and
320	     * address match. Keeping this in one place means the household-equality rule is changed once.
321	     */
322	    private boolean inHousehold(Owner existing, String normalizedLastName, String normalizedAddress) {
323	        return normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
324	            && normalizedAddress.equals(normalizeForComparison(existing.getAddress()));
325	    }
326	
327	    @Override
328	    @Transactional
329	    public String assignHousehold(Owner owner) throws DataAccessException {
330	        String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
331	        owner.setHouseholdId(householdId);
332	        String normalizedLastName = normalizeForComparison(owner.getLastName());
333	        String normalizedAddress = normalizeForComparison(owner.getAddress());
334	        if (normalizedLastName != null && normalizedAddress != null) {
335	            // Back-fill existing members of the household so the joining owner and the
336	            // owner(s) already at the address share the same stable identifier.
337	            for (Owner existing : ownerRepository.findAll()) {
338	                if (existing.getHouseholdId() == null
339	                    && inHousehold(existing, normalizedLastName, normalizedAddress)) {
340	                    existing.setHouseholdId(householdId);
341	                    ownerRepository.save(existing);
342	                }
343	            }
344	        }
345	        return householdId;
346	    }
347	
348	    /**
349	     * Derive a stable household identifier from the normalized last name and address, so that
350	     * every owner sharing a household (same last name and address, compared case-insensitively
351	     * with internal whitespace collapsed) maps to the same value. The identifier is the first
352	     * eight upper-case hex characters of the SHA-256 of {@code <lastName>|<address>}, prefixed
353	     * with {@code 'H-'} (e.g. {@code H-3F5A9C2E}).
354	     */
355	    private String generateHouseholdId(String lastName, String address) {
356	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
357	        try {
358	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
359	            StringBuilder sb = new StringBuilder("H-");
360	            for (int i = 0; i < 4; i++) {
361	                sb.append(String.format("%02X", digest[i]));
362	            }
363	            return sb.toString();
364	        }
365	        catch (NoSuchAlgorithmException e) {
366	            throw new IllegalStateException("SHA-256 not available", e);
367	        }
368	    }
